import { composeRewardText, 归一位阶, 晋升奖励前缀 } from './dice';
import { 基准等级 } from './crTable';
// ================================================================
// 副本生成 · AI 输出校验与变量映射
// 纯函数, 无副作用, 不触碰酒馆接口
// ================================================================
/** 成就梯度档位名, 顺序必须与 dice.ts 的 成就梯度 一致 */
const 成就档位 = [
    '★ 探索级',
    '★★ 挑战级',
    '★★★ 破局级',
    '★★★★ 史诗级',
    '★★★★★ 传说级',
    '★★★★★★ 世界天花板',
];
/** 固有角色位阶枚举（用户的 schema 里 `位阶` 是自由字符串，此处收紧为固定集合） */
export const 固有角色位阶枚举 = ['凡人极限', '一阶', '二阶', '三阶', '四阶', '五阶', '超脱'];
/** 固有角色「位阶 → 等级区间」，依据 <固有角色锚定与战力表现> 的锚定表 */
export const 固有角色阶位区间 = {
    凡人极限: [1, 1],
    一阶: [1, 20],
    二阶: [21, 40],
    三阶: [41, 60],
    四阶: [61, 80],
    五阶: [81, 100],
    超脱: [101, 99999],
};
/** 把等级夹进该阶位的区间；未知阶位原样返回（schema 的 enum 已拦住未知值） */
export function clamp固有角色等级(位阶, 等级) {
    const 区间 = 固有角色阶位区间[位阶];
    if (!区间)
        return 等级;
    return Math.min(Math.max(等级, 区间[0]), 区间[1]);
}
/**
 * 晋升试炼奖励原文（逐字照 `<晋升试炼>` 文档, 下标 = `归一位阶(阶位)` 的返回值 0..3）。
 * 五阶不在表内 —— 用户 2026-09-25 拍板「五阶 Lv.100 不触发」。
 */
export const 晋升奖励表 = [
    '一阶→二阶: 等级上限+20，+3自由属性点，天赋品质强制提升1级。',
    '二阶→三阶: 等级上限+20，+5自由属性点，天赋品质强制提升1级。',
    '三阶→四阶: 等级上限+20，+5自由属性点，天赋品质强制提升1级。',
    '四阶→五阶: 等级上限+20，+8自由属性点，天赋进入完全体形态。',
];
/**
 * 本次该发的晋升奖励原文（含前缀）; `undefined` = 不触发晋升试炼。
 *
 * **唯一一份谓词**: 变量映射与面板文本都调它。分开写就会出现「存档说晋升、复制出去的面板印数值」
 * 的两份打架事实 —— prompt 刚告诉过 AI「你不要输出 UP / EXP / RP 相关文字」。
 *
 * 阶位认不出（`undefined`）与五阶（下标 4, 不在表内）一律不触发 —— 用户 2026-09-25 拍板
 * 「五阶 Lv.100 不触发」。
 */
export function 晋升奖励Of(player) {
    if (!player.晋升试炼)
        return undefined;
    const 下标 = 归一位阶(player.阶位);
    if (下标 === undefined || 下标 > 3)
        return undefined;
    return 晋升奖励前缀 + 晋升奖励表[下标];
}
/**
 * 第 3 条（下标 2）支线的奖励文本。
 *
 * 「**恰好是第 3 条**」是这个功能契约本身（prompt 里也写着「且**恰好是第 3 条**（不改条数）」），
 * 故这个下标判断只在这里写一次 —— 变量映射与面板文本都调它, 两处不可能漂移。
 */
function 支线奖励文本(下标, 晋升奖励, roll, 物品名) {
    return 下标 === 2 && 晋升奖励 ? 晋升奖励 : composeRewardText(roll, 物品名);
}
const 主线任务Schema = z.object({ 名称: z.string(), 说明: z.string() });
const 支线任务Schema = z.object({ 名称: z.string(), 说明: z.string(), 物品名: z.string().prefault('') });
const 隐藏任务Schema = z.object({ 名称: z.string(), 说明: z.string(), 物品名: z.string().prefault('') });
const 世界事件Schema = z.object({ 名称: z.string(), 说明: z.string(), 影响: z.string() });
const 成就Schema = z.object({
    名称: z.string(),
    说明: z.string(),
    难度: z.string(),
    物品名: z.string().prefault(''),
});
/**
 * AI 返回内容的校验 schema。
 * 数组长度用 length 精确约束 —— 状态栏与正则都依赖「3 支线 / 2 隐藏 / 2 世界事件 / 6 成就」这个固定结构。
 */
export const DungeonGenResultSchema = z.object({
    副本名称: z.string().min(1),
    副本来源: z.string().min(1),
    副本背景: z.string().min(1),
    日常调和说明: z.string().prefault(''),
    主线任务: 主线任务Schema,
    支线任务: z.array(支线任务Schema).length(3),
    世界事件: z.array(世界事件Schema).length(2),
    隐藏任务: z.array(隐藏任务Schema).length(2),
    副本成就: z.array(成就Schema).length(6),
    固有角色: z.array(z.object({ 名称: z.string().min(1), 位阶: z.enum(固有角色位阶枚举), 等级: z.coerce.number().int().min(1).max(99999) })),
    其他契约者: z.array(z.object({ 真名: z.string().min(1), 称号: z.string(), 等级: z.coerce.number().int().min(1).max(200), 阵营: z.string() })),
    /**
     * 本次生效的动态事件**强制要求在场**的人物（真名, 逐字）。
     * 由 AI 复述 —— 事件正文是自然语言, 从散文里正则抠名字必然漏（`{{user}}`、称号、全名/简称混用）。
     * `.prefault([])`: 不开事件、或 AI 不回这个字段时都不报错。
     */
    事件点名角色: z.array(z.string()).prefault([]),
});
/**
 * 事件点名了、但名单里找不到的人。
 *
 * 只在 `其他契约者` 与 `固有角色` **两边都找不到**时才算缺席 ——
 * 事件可能点名契约者（如塞拉菲娜、弗尔弗尔）, 也可能点名副本世界的固有角色, 两种都合法。
 *
 * **只报警、不阻断**（由 store 写进 lastError）: AI 的输出仍是最终结果,
 * 照本项目「宁可难看也不圆上」的一贯口径 —— 不静默吞掉, 也不替 AI 改名单。
 */
export function 点名缺席者(result) {
    const 在场 = new Set([
        ...result.其他契约者.map(c => c.真名),
        ...result.固有角色.map(r => r.名称),
    ]);
    return result.事件点名角色.filter(名 => !在场.has(名));
}
/**
 * 把 AI 结果 + 已锁定骰值映射成 `契约者` 下的变量字段。
 * 返回的键名与 schema 中 `契约者` 的子字段同名, 调用方负责逐条 _.set。
 */
export function mapToVariables(result, build, rewards, player) {
    const 当前副本元数据 = {
        副本名称: result.副本名称,
        副本来源: result.副本来源,
        副本类型: build.副本类型,
        // 时间限制是已锁定的骰值 (1d12+2), 不从 AI 结果取, 否则 AI 的措辞会让它与骰值不一致
        时间限制: `${build.时间限制天}天`,
        // 规则 §四: 以契约者进本时的当前等级为基准 —— 再叠上 CR 档的基准等级偏移（+0/+2/+4/+8/+16/+32）。
        // 偏移只算一次: 经 `crTable.基准等级`, 与 `store.generateEnemies` 传给 `buildEnemyPrompt` 的
        // 是**同一个函数**（写进存档的基准等级与敌人实际等级因此不可能漂移）。
        基准等级: 基准等级(player.等级, player.CR),
    };
    // 晋升试炼: 第 3 条支线的奖励**替换**为晋升奖励原文（用户 2026-09-25 拍板「替换掉第 3 条」）。
    // 前缀由 dice.ts 定义, 结算侧 parseRewardText 靠它识别「非数值奖励」。
    // 谓词与下标判断都收在 `晋升奖励Of` / `支线奖励文本` 里, 与 `assemblePanelText` 同源。
    const 晋升奖励 = 晋升奖励Of(player);
    const 支线任务 = {};
    result.支线任务.forEach((t, i) => {
        支线任务[t.名称] = {
            说明: t.说明,
            奖励: 支线奖励文本(i, 晋升奖励, rewards.支线[i], t.物品名),
            状态: '进行中',
        };
    });
    const 世界事件 = {};
    result.世界事件.forEach(e => {
        // 变量里世界事件只有「奖励」字段, 规则给的是「影响」, 故把影响文本落在奖励字段
        世界事件[e.名称] = { 说明: e.说明, 奖励: e.影响, 状态: '进行中' };
    });
    const 隐藏任务 = {};
    result.隐藏任务.forEach((t, i) => {
        隐藏任务[t.名称] = {
            说明: t.说明,
            奖励: composeRewardText(rewards.隐藏[i], t.物品名),
            状态: '未触发',
        };
    });
    const 副本成就 = {};
    result.副本成就.forEach((a, i) => {
        副本成就[a.名称] = {
            说明: a.说明,
            难度: `${成就档位[i]} · ${a.难度}`,
            奖励: composeRewardText(rewards.成就[i], a.物品名),
            状态: '未达成',
        };
    });
    const 固有角色名单 = {};
    result.固有角色.forEach(r => {
        固有角色名单[r.名称] = { 位阶: r.位阶, 等级: clamp固有角色等级(r.位阶, r.等级), 状态: '存活' };
    });
    const 其他契约者名单 = {};
    result.其他契约者.forEach(c => {
        其他契约者名单[c.真名] = {
            称号: c.称号 === '无' || c.称号 === '' ? '无称号' : c.称号,
            等级: c.等级,
            阵营: c.阵营,
            状态: '存活',
        };
    });
    const 主线 = result.主线任务;
    return {
        当前副本元数据,
        当前副本任务: {
            主线任务: {
                名称: 主线.名称,
                说明: 主线.说明,
                奖励: composeRewardText(rewards.主线, ''),
                状态: '进行中',
            },
            支线任务,
            世界事件,
            隐藏任务,
            副本成就,
        },
        固有角色名单,
        其他契约者名单,
    };
}
/** 组装 <Panel Enhancement> 面板文本, 仅用于存档与复制, 不填入输入框 */
export function assemblePanelText(result, build, rewards, player) {
    const L = [];
    // 与 `mapToVariables` 共用同一份晋升谓词与同一条「第 3 条」下标判断 ——
    // 两处若各写一份, 复制出去的面板就会给晋升支线印上数值奖励, 与存档打架。
    const 晋升奖励 = 晋升奖励Of(player);
    L.push('<Panel Enhancement>');
    L.push('<副本任务>');
    L.push(`## 副本名称: ${result.副本名称}`);
    L.push(`## 副本背景: ${result.副本背景}`);
    L.push(`## 副本来源: ${result.副本来源}`);
    L.push(`## 副本类型: 【${build.副本类型}】`);
    L.push(`## 时间限制: ${build.时间限制天}天`);
    L.push('## 主线任务');
    L.push(`名称: ${result.主线任务.名称}`);
    L.push(`描述: ${result.主线任务.说明}`);
    L.push(`奖励: ${composeRewardText(rewards.主线, '')}`);
    L.push('惩罚: 抹杀');
    result.支线任务.forEach((t, i) => {
        L.push(`## 支线任务${i + 1}`);
        L.push(`名称: ${t.名称}`);
        L.push(`描述: ${t.说明}`);
        L.push(`奖励: ${支线奖励文本(i, 晋升奖励, rewards.支线[i], t.物品名)}`);
    });
    result.隐藏任务.forEach((t, i) => {
        L.push(`## 隐藏任务${i + 1}`);
        L.push(`名称: ${t.名称}`);
        L.push(`描述: ${t.说明}`);
        L.push(`奖励: ${composeRewardText(rewards.隐藏[i], t.物品名)}`);
    });
    L.push('</副本任务>');
    L.push('<副本世界事件和成就列表>');
    result.世界事件.forEach((e, i) => {
        L.push(`## 世界事件${i + 1}`);
        L.push(`名称: ${e.名称}`);
        L.push(`描述: ${e.说明}`);
        L.push(`影响: ${e.影响}`);
    });
    L.push('## 副本成就奖励梯度');
    result.副本成就.forEach((a, i) => {
        L.push(`${成就档位[i]}：${a.难度} | ${composeRewardText(rewards.成就[i], a.物品名)}`);
    });
    L.push('</副本世界事件和成就列表>');
    L.push('<副本人物生成>');
    L.push('## 契约者名单');
    const 契约者 = [
        `[契约者]${player.姓名} Lv.${player.等级}`,
        ...result.其他契约者.map(c => `[${c.称号 === '无' || c.称号 === '' ? '无称号' : c.称号}]${c.真名} Lv.${c.等级}`),
    ];
    L.push(`契约者: ${契约者.join('，')}`);
    L.push('## 固有角色');
    L.push(`角色列表: ${result.固有角色.map(r => `${r.名称} (Lv.${clamp固有角色等级(r.位阶, r.等级)} | ${r.位阶})`).join('，')}`);
    L.push('</副本人物生成>');
    L.push('</Panel Enhancement>');
    return L.join('\n');
}
