t width='140' height='140' filter='url(%23n)' opacity='0.55'/%3E%3C/svg%3E\");\n}\n\n// ============ FLOAT BTN ============\n.float-btn {\n  position: fixed;\n  z-index: 2147483640;\n  pointer-events: auto;\n  width: 64px;\n  height: 64px;\n  border-radius: 50%;\n  background: linear-gradient(145deg, #2a2520, #141210);\n  border: 2px solid rgba(200, 160, 100, 0.2);\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  box-shadow:\n    0 4px 24px rgba(0, 0, 0, 0.6),\n    inset 0 1px 0 rgba(220, 180, 120, 0.1);\n  user-select: none;\n  -webkit-user-select: none;\n  touch-action: none;\n  transition:\n    transform 0.2s,\n    box-shadow 0.2s,\n    border-color 0.2s;\n  &:hover {\n    transform: scale(1.06);\n    border-color: rgba(240, 208, 128, 0.4);\n    box-shadow:\n      0 6px 32px rgba(0, 0, 0, 0.7),\n      0 0 0 6px rgba(180, 40, 40, 0.2);\n  }\n  &.dragging {\n    transform: scale(1.1);\n    cursor: grabbing;\n    border-color: rgba(240, 208, 128, 0.6);\n    box-shadow:\n      0 8px 40px rgba(0, 0, 0, 0.7),\n      0 0 0 10px rgba(180, 40, 40, 0.3);\n    transition: none;\n  }\n}\n.btn-core {\n  position: relative;\n  z-index: 2;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n.btn-glyph {\n  width: 30px;\n  height: 30px;\n  color: var(--amber-d);\n  transition: color 0.2s;\n  .float-btn:hover & {\n    color: var(--amber);\n  }\n}\n.btn-halo {\n  position: absolute;\n  inset: -5px;\n  border-radius: 50%;\n  border: 2px solid rgba(180, 40, 40, 0.25);\n  animation: bloodPulse 3s ease-in-out infinite;\n  .float-btn:hover & {\n    border-color: rgba(180, 40, 40, 0.55);\n    animation-duration: 1.5s;\n  }\n  .float-btn.dragging & {\n    border-color: rgba(180, 40, 40, 0.7);\n    animation-duration: 1s;\n  }\n}\n@keyframes bloodPulse {\n  0%,\n  100% {\n    opacity: 0.3;\n    transform: scale(1);\n  }\n  50% {\n    opacity: 0.9;\n    transform: scale(1.07);\n  }\n}\n\n// ============ PANEL / PHONE ============\n.panel-overlay {\n  position: fixed;\n  inset: 0;\n  z-index: 2147483630;\n  pointer-events: auto;\n  background: rgba(0, 0, 0, 0.65);\n  backdrop-filter: blur(4px);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: env(safe-area-inset-top) env(safe-area-inset-right) env(safe-area-inset-bottom) env(safe-area-inset-left);\n}\n.panel-enter-active {\n  transition: opacity 0.35s;\n  .phone-frame {\n    transition:\n      transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1),\n      opacity 0.3s;\n  }\n}\n.panel-leave-active {\n  transition: opacity 0.25s;\n  .phone-frame {\n    transition:\n      transform 0.3s ease-in,\n      opacity 0.2s;\n  }\n}\n.panel-enter-from {\n  opacity: 0;\n  .phone-frame {\n    transform: scale(0.1);\n    opacity: 0;\n  }\n}\n.panel-leave-to {\n  opacity: 0;\n  .phone-frame {\n    transform: scale(0.1);\n    opacity: 0;\n  }\n}\n.phone-frame {\n  width: min(calc(320px * var(--ps, 1)), 92vw);\n  height: min(calc(640px * var(--ps, 1)), 88vh);\n  /* 字体与颜色锁定在小手机内部：font-family/color 均可继承，隔离酒馆页面的环境样式 */\n  font-family: var(--wxhl-font, 'Noto Sans SC', 'PingFang SC', system-ui, sans-serif);\n  color: var(--chalk, #f0e8da);\n  border-radius: 42px;\n  background: linear-gradient(180deg, #241812, #150e0a);\n  border: 2px solid rgba(140, 100, 60, 0.25);\n  box-shadow:\n    0 0 0 6px #2a2520,\n    0 0 0 8px rgba(80, 40, 20, 0.3),\n    0 30px 80px rgba(0, 0, 0, 0.7);\n  position: relative;\n  overflow: hidden;\n  display: flex;\n  flex-direction: column;\n}\n/* 内容层：缩放只作用于它，手机外壳不随之变形。\n   用 transform: scale（**不影响布局**，各浏览器语义一致）而非 zoom：zoom 在部分浏览器\n   只缩放内容渲染、不把除掉的尺寸乘回布局盒，于是内容溢位被裁、框内留白。\n   transform 的确定性做法：宽高先除以 --cz（布局盒变小），再以左上角为原点放大 --cz 倍，\n   渲染结果正好等于手机框内尺寸 —— 铺满、不溢位、不裁切。\n   --cz = --ps × --fs：手机尺寸把窗口与内容等比放大，字体大小再额外放大文字。 */\n.phone-content {\n  flex: none;\n  width: calc(100% / var(--cz, 1));\n  height: calc(100% / var(--cz, 1));\n  transform: scale(var(--cz, 1));\n  transform-origin: top left;\n  display: flex;\n  flex-direction: column;\n  min-height: 0;\n  overflow: hidden;\n}\n/* 手机外壳四角铆钉 */\n.phone-frame::before {\n  content: '';\n  position: absolute;\n  inset: 8px;\n  pointer-events: none;\n  z-index: 30;\n  background:\n    radial-gradient(circle 2.5px at 14px 14px, rgba(200, 160, 110, 0.5) 50%, transparent 51%),\n    radial-gradient(circle 2.5px at calc(100% - 14px) 14px, rgba(200, 160, 110, 0.5) 50%, transparent 51%),\n    radial-gradient(circle 2.5px at 14px calc(100% - 14px), rgba(200, 160, 110, 0.5) 50%, transparent 51%),\n    radial-gradient(circle 2.5px at calc(100% - 14px) calc(100% - 14px), rgba(200, 160, 110, 0.5) 50%, transparent 51%);\n}\n.status-bar {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 12px 28px 0;\n  height: 32px;\n  flex-shrink: 0;\n  font-size: 11px;\n  color: var(--amber-d);\n  font-family: 'Courier New', monospace;\n}\n.status-label {\n  font-size: 10px;\n  letter-spacing: 2px;\n  color: var(--blood-b);\n}\n.minimize-btn {\n  position: absolute;\n  top: 36px;\n  right: 16px;\n  z-index: 20;\n  width: 26px;\n  height: 26px;\n  border-radius: 50%;\n  border: 1.5px solid rgba(200, 160, 100, 0.25);\n  background: rgba(20, 14, 10, 0.8);\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  transition: all 0.2s;\n  span {\n    display: block;\n    width: 10px;\n    height: 1.5px;\n    background: rgba(240, 208, 128, 0.7);\n    border-radius: 1px;\n  }\n  &:hover {\n    background: rgba(180, 40, 40, 0.25);\n    border-color: rgba(180, 40, 40, 0.5);\n  }\n}\n\n// ============ DESKTOP ============\n.desktop-view {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  position: relative;\n}\n/* 主页面滚动层：背景/页脚留在原地，内容超出时可滚（滚动条隐藏） */\n.desktop-scroll {\n  position: relative;\n  z-index: 2;\n  flex: 1;\n  min-height: 0;\n  overflow-y: auto;\n  -webkit-overflow-scrolling: touch;\n  scrollbar-width: none;\n  -ms-overflow-style: none;\n  &::-webkit-scrollbar {\n    display: none;\n  }\n}\n.corridor-bg {\n  position: absolute;\n  inset: 0;\n  overflow: hidden;\n  background: #150e0a;\n  /* 顶部吊灯光锥 */\n  &::before {\n    content: '';\n    position: absolute;\n    top: 0;\n    left: 50%;\n    transform: translateX(-50%);\n    width: 70%;\n    height: 60%;\n    background: radial-gradient(\n      ellipse at 50% 0%,\n      rgba(240, 208, 128, 0.12) 0%,\n      rgba(240, 208, 128, 0.04) 45%,\n      transparent 70%\n    );\n    pointer-events: none;\n    z-index: 1;\n  }\n  /* 墙面颗粒 */\n  &::after {\n    content: '';\n    position: absolute;\n    inset: 0;\n    background-image: var(--grain);\n    opacity: 0.14;\n    mix-blend-mode: overlay;\n    pointer-events: none;\n    z-index: 1;\n  }\n}\n.corridor-ceiling {\n  position: absolute;\n  top: 0;\n  left: 0;\n  right: 0;\n  height: 30%;\n  background: linear-gradient(180deg, #181410, #100c09 60%, #0c0806);\n  border-bottom: 1px solid rgba(80, 40, 20, 0.35);\n  &::after {\n    content: '';\n    position: absolute;\n    bottom: 0;\n    left: 20%;\n    right: 20%;\n    height: 1px;\n    background: rgba(200, 40, 30, 0.35);\n    box-shadow: 0 0 8px rgba(200, 40, 30, 0.25);\n  }\n}\n.corridor-left {\n  position: absolute;\n  top: 30%;\n  left: 0;\n  bottom: 25%;\n  width: 25%;\n  background: linear-gradient(90deg, rgba(30, 15, 8, 0.9), rgba(15, 8, 4, 0.4));\n  clip-path: polygon(0 0, 100% 8%, 100% 92%, 0 100%);\n  &::before {\n    content: '';\n    position: absolute;\n    inset: 0;\n    background:\n      radial-gradient(ellipse at 40% 30%, rgba(80, 20, 12, 0.45), transparent 60%),\n      radial-gradient(ellipse at 60% 70%, rgba(50, 14, 8, 0.35), transparent 50%);\n    animation: fleshPulse 4s ease-in-out infinite;\n  }\n}\n.corridor-right {\n  position: absolute;\n  top: 30%;\n  right: 0;\n  bottom: 25%;\n  width: 25%;\n  background: linear-gradient(270deg, rgba(30, 15, 8, 0.9), rgba(15, 8, 4, 0.4));\n  clip-path: polygon(0 8%, 100% 0, 100% 100%, 0 92%);\n  &::before {\n    content: '';\n    position: absolute;\n    inset: 0;\n    background:\n      radial-gradient(ellipse at 60% 40%, rgba(80, 20, 12, 0.4), transparent 55%),\n      radial-gradient(ellipse at 30% 60%, rgba(50, 14, 8, 0.35), transparent 50%);\n    animation: fleshPulse 4.5s ease-in-out infinite 1s;\n  }\n}\n.corridor-floor {\n  position: absolute;\n  bottom: 0;\n  left: 0;\n  right: 0;\n  height: 25%;\n  background: linear-gradient(0deg, #0e0a06, #0a0805 60%, transparent);\n  background-image:\n    linear-gradient(90deg, rgba(60, 35, 20, 0.25) 1px, transparent 1px),\n    linear-gradient(0deg, rgba(60, 35, 20, 0.2) 1px, transparent 1px);\n  background-size: 30px 30px;\n  border-top: 1px solid rgba(70, 35, 20, 0.35);\n}\n.corridor-end {\n  position: absolute;\n  top: 30%;\n  left: 25%;\n  right: 25%;\n  bottom: 25%;\n  background: radial-gradient(ellipse at center, rgba(200, 40, 25, 0.2), transparent 70%);\n  animation: endBreathe 3s ease-in-out infinite;\n}\n@keyframes fleshPulse {\n  0%,\n  100% {\n    opacity: 0.7;\n  }\n  50% {\n    opacity: 1;\n  }\n}\n@keyframes endBreathe {\n  0%,\n  100% {\n    opacity: 0.5;\n    transform: scale(1);\n  }\n  50% {\n    opacity: 0.9;\n    transform: scale(1.03);\n  }\n}\n.app-grid {\n  position: relative;\n  z-index: 2;\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 18px 8px;\n  padding: 20px 14px 0;\n  justify-items: center;\n}\n.app-icon-wrapper {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 4px;\n  cursor: pointer;\n  transition: transform 0.15s;\n  &:active {\n    transform: scale(0.88);\n  }\n}\n.app-icon {\n  position: relative;\n  width: 60px;\n  height: 60px;\n  border-radius: 15px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.5);\n  transition: box-shadow 0.2s;\n  /* 铭牌铆钉角 */\n  &::after {\n    content: '';\n    position: absolute;\n    inset: 4px;\n    pointer-events: none;\n    background:\n      radial-gradient(circle 1.5px at 5px 5px, rgba(240, 208, 128, 0.5) 50%, transparent 51%),\n      radial-gradient(circle 1.5px at calc(100% - 5px) 5px, rgba(240, 208, 128, 0.5) 50%, transparent 51%),\n      radial-gradient(circle 1.5px at 5px calc(100% - 5px), rgba(240, 208, 128, 0.5) 50%, transparent 51%),\n      radial-gradient(circle 1.5px at calc(100% - 5px) calc(100% - 5px), rgba(240, 208, 128, 0.5) 50%, transparent 51%);\n  }\n  .app-icon-wrapper:hover & {\n    box-shadow:\n      0 8px 30px rgba(0, 0, 0, 0.7),\n      0 0 20px rgba(180, 40, 40, 0.35);\n  }\n  svg {\n    width: 28px;\n    height: 28px;\n    color: var(--amber-d);\n    filter: drop-shadow(0 0 4px rgba(240, 208, 128, 0.35));\n  }\n}\n.forum-icon {\n  background: linear-gradient(135deg, #3a1a10, #201008);\n  border: 1.5px solid rgba(240, 208, 128, 0.25);\n}\n.settings-icon {\n  background: linear-gradient(135deg, #2a2825, #181410);\n  border: 1.5px solid rgba(200, 140, 100, 0.25);\n}\n.crafting-icon {\n  background: linear-gradient(135deg, #3a2410, #20140a);\n  border: 1.5px solid rgba(200, 150, 80, 0.3);\n}\n.app-label {\n  font-size: 11px;\n  color: var(--chalk);\n  letter-spacing: 2px;\n  font-family: 'Noto Serif SC', serif;\n  margin-top: 4px;\n}\n.app-sub {\n  font-size: 9px;\n  color: var(--chalk-d);\n  letter-spacing: 1px;\n  font-family: 'Courier New', monospace;\n}\n.idle-plate {\n  position: relative;\n  z-index: 2;\n  margin: 18px 20px 0;\n  padding: 14px 12px 12px;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 4px;\n  cursor: pointer;\n  background:\n    radial-gradient(circle 2px at 8px 8px, rgba(240, 208, 128, 0.45) 50%, transparent 51%),\n    radial-gradient(circle 2px at calc(100% - 8px) 8px, rgba(240, 208, 128, 0.45) 50%, transparent 51%),\n    radial-gradient(circle 2px at 8px calc(100% - 8px), rgba(240, 208, 128, 0.45) 50%, transparent 51%),\n    radial-gradient(circle 2px at calc(100% - 8px) calc(100% - 8px), rgba(240, 208, 128, 0.45) 50%, transparent 51%),\n    linear-gradient(180deg, rgba(36, 24, 18, 0.92), rgba(21, 14, 10, 0.9));\n  border: 2px solid var(--iron);\n  box-shadow:\n    inset 0 0 24px rgba(0, 0, 0, 0.5),\n    0 6px 20px rgba(0, 0, 0, 0.4);\n  transition: all 0.3s;\n  &:hover {\n    border-color: var(--amber-d);\n    filter: brightness(1.15);\n  }\n}\n.ip-title {\n  font-family: 'Noto Serif SC', serif;\n  font-size: 10px;\n  letter-spacing: 4px;\n  color: var(--amber-d);\n}\n.ip-name {\n  font-family: 'Noto Serif SC', serif;\n  font-size: 22px;\n  font-weight: 900;\n  letter-spacing: 3px;\n  color: var(--amber);\n  text-shadow: 0 0 12px rgba(240, 208, 128, 0.4);\n}\n.ip-line {\n  font-family: 'Courier New', monospace;\n  font-size: 11px;\n  color: var(--chalk);\n  letter-spacing: 1px;\n}\n.ip-bars {\n  display: flex;\n  gap: 10px;\n  margin-top: 6px;\n}\n.ip-bar {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n}\n.ip-bl {\n  font-size: 9px;\n  color: var(--amber-d);\n  font-family: 'Noto Serif SC', serif;\n  letter-spacing: 1px;\n}\n.ip-track {\n  position: relative;\n  width: 52px;\n  height: 5px;\n  background: rgba(20, 12, 8, 0.6);\n  border: 1px solid rgba(100, 50, 20, 0.3);\n  border-radius: 2px;\n  overflow: hidden;\n  &::after {\n    content: '';\n    position: absolute;\n    inset: 0;\n    background: repeating-linear-gradient(90deg, transparent 0 7px, rgba(0, 0, 0, 0.55) 7px 8px);\n    pointer-events: none;\n  }\n}\n.ip-fill {\n  height: 100%;\n  transition: width 0.6s;\n  &.hp {\n    background: linear-gradient(90deg, #2a0808, #8a2020);\n  }\n  &.mp {\n    background: linear-gradient(90deg, #1a2a22, #4a7060);\n  }\n  &.sp {\n    background: linear-gradient(90deg, #2a1008, #5a2812);\n  }\n}\n.desktop-pager {\n  position: absolute;\n  bottom: 50px;\n  left: 0;\n  right: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 14px;\n  z-index: 2;\n}\n.pager-arrow {\n  background: none;\n  border: 1px solid var(--amber-d, rgba(180, 140, 60, 0.6));\n  color: var(--amber-d, rgba(180, 140, 60, 0.6));\n  border-radius: 50%;\n  width: 26px;\n  height: 26px;\n  font-size: 15px;\n  line-height: 1;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n.pager-arrow:disabled {\n  opacity: 0.3;\n  cursor: default;\n}\n.pager-dot {\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background: rgba(127, 127, 127, 0.4);\n  cursor: pointer;\n}\n.pager-dot.on {\n  background: var(--amber-d, #b48c3c);\n}\n.desktop-footer {\n  position: absolute;\n  bottom: 30px;\n  left: 0;\n  right: 0;\n  text-align: center;\n  z-index: 2;\n  font-size: 10px;\n  color: var(--amber-d);\n  letter-spacing: 4px;\n  opacity: 0.6;\n}\n\n// ============ APP PAGE ============\n.app-page {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  background: linear-gradient(180deg, #1a1410, #100c09);\n  position: relative;\n  z-index: 5;\n  min-height: 0;\n}\n.app-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0 12px;\n  height: 44px;\n  flex-shrink: 0;\n  background: rgba(30, 20, 14, 0.95);\n  border-bottom: 1px solid rgba(80, 40, 20, 0.35);\n}\n.hdr-btn {\n  width: 36px;\n  height: 36px;\n  border: none;\n  background: transparent;\n  color: var(--amber-d);\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 50%;\n  flex-shrink: 0;\n  svg {\n    width: 18px;\n    height: 18px;\n  }\n  &:hover {\n    background: rgba(255, 255, 255, 0.05);\n  }\n}\n.hdr-title {\n  font-size: 13px;\n  font-weight: 600;\n  color: var(--chalk);\n  letter-spacing: 1px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  max-width: 200px;\n  text-align: center;\n}\n.hdr-spacer {\n  width: 36px;\n  flex-shrink: 0;\n}\n\n// ============ SCROLL ============\n// 各处滚动容器统一隐藏滚动条（滚动功能保留）\n.scroll-area {\n  flex: 1;\n  overflow-y: auto;\n  overflow-x: hidden;\n  -webkit-overflow-scrolling: touch;\n  overscroll-behavior: contain;\n  min-height: