in-left: auto;\n  }\n  .dp-content {\n    font-size: 12px;\n    color: var(--chalk);\n    line-height: 1.6;\n    white-space: pre-wrap;\n    word-break: break-word;\n  }\n}\n.reply-bar {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 8px 12px;\n  flex-shrink: 0;\n  background: rgba(30, 20, 14, 0.95);\n  border-top: 1px solid rgba(80, 40, 20, 0.3);\n}\n.reply-input {\n  flex: 1;\n  padding: 7px 10px;\n  background: rgba(16, 12, 8, 0.7);\n  border: 1px solid rgba(80, 40, 20, 0.35);\n  border-radius: 6px;\n  color: var(--chalk);\n  font-size: 11px;\n  outline: none;\n  &::placeholder {\n    color: var(--chalk-d);\n    opacity: 0.5;\n  }\n  &:focus {\n    border-color: rgba(180, 40, 40, 0.5);\n  }\n}\n.reply-btn {\n  flex-shrink: 0;\n  padding: 7px 14px;\n  background: rgba(180, 40, 40, 0.25);\n  border: 1px solid rgba(180, 40, 40, 0.4);\n  color: var(--amber);\n  font-size: 11px;\n  border-radius: 6px;\n  cursor: pointer;\n  &:hover {\n    background: rgba(180, 40, 40, 0.4);\n  }\n  &:disabled {\n    opacity: 0.3;\n    cursor: default;\n  }\n}\n.reply-wait {\n  font-size: 10px;\n  color: var(--amber-d);\n  white-space: nowrap;\n}\n.gen-overlay {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 12px;\n  color: var(--amber-d);\n  font-size: 12px;\n}\n.gen-spinner {\n  width: 32px;\n  height: 32px;\n  border: 3px solid rgba(180, 40, 40, 0.2);\n  border-top-color: var(--amber);\n  border-radius: 50%;\n  animation: spin 0.8s linear infinite;\n}\n.d-post.nest1 {\n  margin-left: 16px;\n  border-left: 2px solid rgba(100, 140, 180, 0.3);\n}\n.d-post.nest2 {\n  margin-left: 32px;\n  border-left: 2px solid rgba(140, 100, 60, 0.25);\n}\n.retry-link {\n  background: transparent;\n  border: none;\n  color: var(--amber);\n  cursor: pointer;\n  text-decoration: underline;\n  font-size: 11px;\n}\n\n// ============ SETTINGS MENU ============\n.settings-menu {\n  padding: 8px 12px;\n  display: flex;\n