h: 100%;\n  margin-top: 8px;\n  padding: 8px;\n  background: rgba(60, 100, 140, 0.2);\n  border: 1px solid rgba(80, 120, 160, 0.4);\n  color: #90c0e0;\n  font-size: 11px;\n  border-radius: 6px;\n  cursor: pointer;\n  transition: all 0.2s;\n  &:hover {\n    background: rgba(60, 100, 140, 0.35);\n  }\n  &:disabled {\n    opacity: 0.4;\n  }\n}\n.test-msg {\n  margin-top: 6px;\n  padding: 6px 10px;\n  background: rgba(180, 40, 40, 0.1);\n  border: 1px solid rgba(180, 40, 40, 0.3);\n  border-radius: 4px;\n  font-size: 10px;\n  color: var(--blood-b);\n  word-break: break-all;\n  &.ok {\n    background: rgba(40, 140, 80, 0.1);\n    border-color: rgba(40, 140, 80, 0.3);\n    color: #60d080;\n  }\n}\n.wb-load-btn {\n  display: block;\n  width: 100%;\n  margin-bottom: 6px;\n  padding: 6px;\n  background: rgba(100, 80, 40, 0.15);\n  border: 1px solid rgba(140, 100, 40, 0.3);\n  color: var(--amber-d);\n  font-size: 10px;\n  border-radius: 4px;\n  cursor: pointer;\n  &:hover {\n    background: rgba(100, 80, 40, 0.25);\n  }\n}\n.wb-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 5px 8px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background 0.1s;\n  &:hover {\n    background: rgba(255, 255, 255, 0.03);\n  }\n}\n.wb-check {\n  font-size: 12px;\n  color: var(--chalk-d);\n  &.on {\n    color: var(--amber);\n  }\n}\n.wb-name {\n  font-size: 11px;\n  color: var(--chalk);\n}\n.wb-search-row {\n  display: flex;\n  gap: 6px;\n  margin-bottom: 6px;\n}\n.wb-search {\n  flex: 1;\n  min-width: 0;\n  padding: 6px 8px;\n  background: rgba(16, 12, 8, 0.7);\n  border: 1px solid rgba(80, 40, 20, 0.35);\n  border-radius: 4px;\n  color: var(--chalk);\n  font-size: 11px;\n  outline: none;\n  &::placeholder {\n    color: var(--chalk-d);\n    opacity: 0.5;\n  }\n  &:focus {\n    border-color: rgba(180, 40, 40, 0.5);\n  }\n}\n.wb-block {\n  margin-bottom: 2px;\n}\n.wb-expand {\n  margin-left: auto;\n  flex-shrink: 0;\n  width: 22px;\n  height: 22px;\n  background: transparent;\n  border: 1px solid rgba(80, 40, 20, 0.3);\n  border-radius: 4px;\n  color: var(--amber-d);\n  font-size: 10px;\n  line-height: 1;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  &:hover {\n    background: rgba(255, 255, 255, 0.05);\n  }\n}\n.wb-entries {\n  padding: 4px 0 6px 10px;\n  border-left: 1px solid rgba(80, 40, 20, 0.25);\n  margin: 0 0 4px 8px;\n}\n.wb-entry-actions {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  margin-bottom: 4px;\n  flex-wrap: wrap;\n}\n.wb-mini {\n  padding: 3px 8px;\n  background: rgba(100, 80, 40, 0.15);\n  border: 1px solid rgba(140, 100, 40, 0.3);\n  color: var(--amber-d);\n  font-size: 10px;\n  border-radius: 4px;\n  cursor: pointer;\n  &:hover {\n    background: rgba(100, 80, 40, 0.25);\n  }\n}\n.wb-count {\n  font-size: 10px;\n  color: var(--chalk-d);\n  opacity: 0.7;\n  margin-left: auto;\n}\n.wb-entry {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 3px 6px;\n  cursor: pointer;\n  border-radius: 4px;\n  transition: background 0.1s;\n  &:hover {\n    background: rgba(255, 255, 255, 0.03);\n  }\n}\n.wb-entry-name {\n  font-size: 11px;\n  color: var(--chalk-d);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.prof-select {\n  flex: 1;\n  min-width: 0;\n  padding: 6px 8px;\n  background: rgba(16, 12, 8, 0.7);\n  border: 1px solid rgba(80, 40, 20, 0.35);\n  border-radius: 4px;\n  color: var(--chalk);\n  font-size: 11px;\n  outline: none;\n  &:focus {\n    border-color: rgba(180, 40, 40, 0.5);\n  }\n}\n.set-row .test-btn {\n  width: auto;\n  flex-shrink: 0;\n  margin-top: 0;\n  padding: 6px 10px;\n  white-space: nowrap;\n}\n\n// ============ WALLPAPER ============\n.wp-preview {\n  width: 100%;\n  height: 120px;\n  border-radius: 8px;\n  border: 1px solid rgba(80, 40, 20, 0.35);\n  margin-bottom: 8px;\n  background: var(--bg);\n}\n.wp-clear-btn {\n  display: block;\n  width: 100%;\n  padding: 6px;\n  background: rgba(180, 40, 40, 0.15);\n  border: 1px solid rgba(180, 40, 40, 0.3);\n  color: var(--amber-d);\n  font-size: 10px;\n  border-radius: 4px;\n  cursor: pointer;\n  &:hover {\n    background: rgba(180, 40, 40, 0.25);\n  }\n}\n.wp-upload-btn {\n  display: block;\n  width: 100%;\n  padding: 10px;\n  background: rgba(60, 100, 140, 0.15);\n  border: 1px solid rgba(80, 120, 160, 0.3);\n  color: #90c0e0;\n  font-size: 12px;\n  border-radius: 6px;\n  cursor: pointer;\n  text-align: center;\n  transition: all 0.2s;\n  &:hover {\n    background: rgba(60, 100, 140, 0.25);\n  }\n}\n.wp-grid {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 8px;\n}\n.wp-preset {\n  cursor: pointer;\n  text-align: center;\n  transition: transform 0.15s;\n  &:hover {\n    transform: scale(1.03);\n  }\n  &.selected {\n    .wp-preset-img {\n      border-color: var(--amber);\n      box-shadow: 0 0 12px rgba(240, 208, 128, 0.3);\n    }\n  }\n}\n.wp-preset-img {\n  width: 100%;\n  aspect-ratio: 9/16;\n  border-radius: 6px;\n  border: 2px solid rgba(80, 40, 20, 0.3);\n  background-size: cover;\n  background-position: center;\n  background-color: var(--bg);\n}\n.wp-preset-label {\n  font-size: 10px;\n  color: var(--chalk-d);\n  margin-top: 4px;\n  display: block;\n}\n\n// ============ MISC ============\n.set-err {\n  margin-top: 8px;\n  padding: 8px 12px;\n  background: rgba(180, 40, 40, 0.12);\n  border: 1px solid rgba(180, 40, 40, 0.35);\n  border-radius: 6px;\n  font-size: 11px;\n  color: var(--blood-b);\n}\n.refresh-err {\n  padding: 8px 12px;\n  margin: 4px 8px;\n  background: rgba(180, 40, 40, 0.12);\n  border: 1px solid rgba(180, 40, 40, 0.3);\n  border-radius: 6px;\n  font-size: 10px;\n  color: var(--blood-b);\n}\n.empty-msg {\n  text-align: center;\n  padding: 30px 0;\n  color: var(--chalk-d);\n  font-size: 12px;\n  opacity: 0.7;\n}\n\n// ============ RESPONSIVE: mobile / tablet device modes ============\n// CSS !important 权重高于 Vue :style 内联样式，自动覆盖非拖动时的位置\n.float-btn.float-btn.float-btn.mobile-mode:not(.dragging) {\n  left: auto !important;\n  top: auto !important;\n  right: 12px !important;\n  bottom: 24px !important;\n  width: 48px !important;\n  height: 48px !important;\n  transform: none !important;\n}\n.float-btn.float-btn.float-btn.tablet-mode:not(.dragging) {\n  left: auto !important;\n  top: auto !important;\n  right: 15px !important;\n  bottom: 15px !important;\n  width: 54px !important;\n  height: 54px !important;\n  transform: none !important;\n}\n@media (max-width: 480px) {\n  .phone-frame.phone-frame {\n    width: 94vw !important;\n    max-width: 100% !important;\n    height: 88vh !important;\n    height: 88dvh !important;\n    max-height: calc(100vh - 20px) !important;\n    max-height: calc(100dvh - 20px) !important;\n    border-radius: 28px !important;\n  }\n}\n@media (min-width: 481px) and (max-width: 768px) {\n  .phone-frame.phone-frame {\n    width: calc(320px * var(--ps, 1)) !important;\n    max-width: 92vw !important;\n    height: calc(600px * var(--ps, 1)) !important;\n    max-height: calc(100vh - 30px) !important;\n    max-height: calc(100dvh - 30px) !important;\n  }\n}\n\n// ============ CAREER ICON ============\n.career-icon {\n  background: linear-gradient(135deg, #2a2010, #1a1008);\n  border: 1.5px solid rgba(200, 180, 100, 0.25);\n}\n.dungeon-icon {\n  background: linear-gradient(135deg, #1a1420, #0c0810);\n  border: 1.5px solid rgba(140, 100, 200, 0.25);\n}\n.arena-icon {\n  background: linear-gradient(135deg, #1a2220, #0c1210);\n  border: 1.5px solid rgba(120, 180, 200, 0.25);\n}\n\n// ============ DIALOG ============\n.dialog-mask {\n  position: absolute;\n  inset: 0;\n  z-index: 30;\n  background: rgba(0, 0, 0, 0.7);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n.dialog-box {\n  width: 88%;\n  max-width: 280px;\n  background: linear-gradient(180deg, #201810, #14100a);\n  border: 1px solid rgba(140, 100, 40, 0.35);\n  border-radius: 12px;\n  padding: 16px;\n  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.8);\n}\n.dialog-title {\n  font-size: 13px;\n  color: var(--amber);\n  font-weight: 600;\n  margin-bottom: 10px;\n  letter-spacing: 1px;\n}\n.dialog-body {\n  font-size: 11px;\n  color: var(--chalk-d);\n  margin-bottom: 12px;\n  line-height: 1.5;\n}\n.dialog-input {\n  width: 100%;\n  padding: 10px;\n  background: rgba(16, 12, 8, 0.8);\n  border: 1px solid rgba(80, 40, 20, 0.4);\n  border-radius: 8px;\n  color: var(--chalk);\n  font-size: 11px;\n  resize: none;\n  outline: none;\n  font-family: inherit;\n  &::placeholder {\n    color: var(--chalk-d);\n    opacity: 0.5;\n  }\n  &:focus {\n    border-color: rgba(180, 40, 40, 0.5);\n  }\n}\n.dialog-btns {\n  display: flex;\n  gap: 8px;\n  margin-top: 12px;\n  justify-content: flex-end;\n}\n.dialog-btn {\n  padding: 7px 18px;\n  border-radius: 6px;\n  font-size: 11px;\n  cursor: pointer;\n  border: 1px solid transparent;\n  transition: all 0.2s;\n  &.cancel {\n    background: transparent;\n    color: var(--chalk-d);\n    border-color: rgba(80, 40, 20, 0.3);\n    &:hover {\n      color: var(--chalk);\n    }\n  }\n  &.confirm {\n    background: rgba(180, 40, 40, 0.2);\n    border-color: rgba(180, 40, 40, 0.4);\n    color: var(--amber);\n    &:hover {\n      background: rgba(180, 40, 40, 0.35);\n    }\n    &:disabled {\n      opacity: 0.3;\n      cursor: default;\n    }\n  }\n  &.danger {\n    background: rgba(180, 40, 40, 0.3);\n    border-color: rgba(180, 40, 40, 0.5);\n    color: #f06050;\n    &:hover {\n      background: rgba(180, 40, 40, 0.5);\n    }\n  }\n}\n\n// ============ DUNGEON WIZARD ============\n.dungeon-faction-row {\n  display: flex;\n  gap: 6px;\n  margin-bottom: 4px;\n}\n.faction-btn {\n  flex: 1;\n  padding: 10px 0;\n  background: rgba(16, 12, 8, 0.7);\n  border: 1px solid rgba(80, 40, 20, 0.3);\n  color: var(--chalk-d);\n  font-size: 12px;\n  border-radius: 6px;\n  cursor: pointer;\n  transition: all 0.2s;\n  &:hover {\n    color: var(--chalk);\n  }\n  &.active {\n    background: rgba(240, 208, 128, 0.15);\n    border-color: rgba(240, 208, 128, 0.5);\n    color: var(--amber);\n    font-weight: 600;\n  }\n}\n.dungeon-choice-btn {\n  display: block;\n  width: 100%;\n  padding: 12px;\n  margin-bottom: 8px;\n  background: rgba(30, 18, 12, 0.5);\n  border: 1px solid rgba(80, 40, 20, 0.3);\n  border-radius: 8px;\n  color: var(--chalk);\n  font-size: 13px;\n  cursor: pointer;\n  transition: all 0.2s;\n  &:hover {\n    background: rgba(180, 40, 40, 0.12);\n    border-color: rgba(180, 40, 40, 0.4);\n  }\n}\n.dungeon-mode-btn {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  width: 100%;\n  padding: 10px 12px;\n  margin-bottom: 6px;\n  background: rgba(16, 12, 8, 0.7);\n  border: 1px solid rgba(80, 40, 20, 0.3);\n  border-radius: 8px;\n  color: var(--chalk);\n  font-size: 12px;\n  cursor: pointer;\n  text-align: left;\n  transition: all 0.2s;\n  &:hover {\n    border-color: rgba(180, 40, 40, 0.4);\n  }\n  &.active {\n    background: rgba(180, 40, 40, 0.15);\n    border-color: rgba(180, 40, 40, 0.5);\n  }\n  .dm-icon {\n    font-size: 18px;\n    flex-shrink: 0;\n  }\n  .dm-text {\n    display: flex;\n    flex-direction: column;\n    gap: 2px;\n  }\n  b {\n    font-size: 12px;\n    color: var(--chalk);\n  }\n  i {\n    font-size: 10px;\n    color: var(--chalk-d);\n    font-style: normal;\n  }\n}\n\n// ============ CAREER LIST ============\n.empty-state {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  padding: 30px 20px;\n  text-align: center;\n}\n.empty-icon {\n  font-size: 40px;\n  margin-bottom: 12px;\n  opacity: 0.6;\n}\n.empty-text {\n  font-size: 14px;\n  color: var(--chalk);\n  margin-bottom: 6px;\n  font-weight: 500;\n}\n.empty-sub {\n  font-size: 11px;\n  color: var(--chalk-d);\n  line-height: 1.5;\n  max-width: 240px;\n}\n.plan-card {\n  padding: 12px 14px;\n  cursor: pointer;\n  border-bottom: 1px solid rgba(80, 40, 20, 0.18);\n  transition: background 0.1s;\n  &:hover {\n    background: rgba(255, 255, 255, 0.03);\n  }\n}\n.pc-top {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 4px;\n}\n.pc-name {\n  font-size: 13px;\n  color: var(--chalk);\n  font-weight: 600;\n}\n.pc-rarity {\n  font-size: 10px;\n  padding: 2px 8px;\n  border-radius: 4px;\n  font-weight: 500;\n  &.rarity-白色 {\n    background: rgba(180, 180, 180, 0.15);\n    color: #c0c0c0;\n  }\n  &.rarity-蓝色 {\n    background: rgba(80, 140, 220, 0.15);\n    color: #80b0e0;\n  }\n  &.rarity-金色 {\n    background: rgba(240, 200, 40, 0.15);\n    color: #f0c028;\n  }\n  &.rarity-紫色 {\n    background: rgba(160, 80, 220, 0.15);\n    color: #a050dc;\n  }\n  &.rarity-银色 {\n    background: rgba(200, 200, 220, 0.15);\n    color: #c8c8dc;\n  }\n}\n.pc-concept {\n  font-size: 11px;\n  color: var(--chalk-d);\n  margin-bottom: 6px;\n  line-height: 1.4;\n}\n.pc-meta {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  font-size: 10px;\n}\n.pc-tag {\n  color: var(--amber-d);\n  background: rgba(240, 208, 128, 0.08);\n  padding: 1px 6px;\n  border-radius: 3px;\n  max-width: 140px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.pc-time {\n  color: var(--chalk-d);\n  opacity: 0.6;\n}\n.pc-phase {\n  padding: 1px 6px;\n  border-radius: 3px;\n  &.pending {\n    background: rgba(180, 140, 40, 0.15);\n    color: var(--amber-d);\n  }\n  &.done {\n    background: rgba(40, 140, 80, 0.12);\n    color: #60d080;\n  }\n}\n.career-fab {\n  flex-shrink: 0;\n  padding: 10px 14px;\n  display: flex;\n  justify-content: center;\n}\n.fab-btn {\n  width: 100%;\n  padding: 10px;\n  background: rgba(180, 40, 40, 0.15);\n  border: 1px solid rgba(180, 40, 40, 0.35);\n  color: var(--amber);\n  font-size: 13px;\n  border-radius: 8px;\n  cursor: pointer;\n  letter-spacing: 1px;\n  transition: all 0.2s;\n  &:hover {\n    background: rgba(180, 40, 40, 0.28);\n    border-color: rgba(180, 40, 40, 0.5);\n  }\n}\n\n// ============ CAREER DETAIL 